<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';const email=ref('admin@stockflow.local'),password=ref('StockFlow123!'),error=ref(''),busy=ref(false),auth=useAuthStore(),router=useRouter();async function submit(){busy.value=true;error.value='';try{await auth.login(email.value,password.value);router.push('/')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}</script>
<template><main class="login"><section class="w-full max-w-md bg-white rounded-3xl shadow-xl p-8"><div class="logo mb-6">SF</div><p class="eyebrow">WELCOME BACK</p><h1 class="text-3xl font-bold mt-2">Sign in to StockFlow</h1><p class="text-slate-500 mt-2 mb-7">Manage inventory and orders with confidence.</p><form @submit.prevent="submit" class="space-y-5"><label>Email address<input v-model="email" type="email" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="alert">{{error}}</p><button class="primary w-full" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form><p class="text-sm text-slate-500 mt-6">Demo credentials are filled in for you.</p></section></main></template>
